package com.aoo.bcg.poker;
public final class PaoDeKuaiFamily implements PokerRuleFamily{public static final String CODE="poker:pao-de-kuai";private final PaoDeKuaiRuleSet rules;private final PokerRuleProfile profile;public PaoDeKuaiFamily(PaoDeKuaiConfig c){this(c,PokerRuleProfile.fromConfig("pdk-v1",52,c));}public PaoDeKuaiFamily(PaoDeKuaiConfig c,PokerRuleProfile p){profile=java.util.Objects.requireNonNull(p);rules=new PaoDeKuaiRuleSet(c,p);}public String familyCode(){return CODE;}public PokerRuleSet<?>ruleSet(){return rules;}public PaoDeKuaiRuleSet rules(){return rules;}public PokerRuleProfile profile(){return profile;}public String ruleSnapshotKey(){try{byte[]hash=java.security.MessageDigest.getInstance("SHA-256").digest((profile.toString()+"|"+rules.config()).getBytes(java.nio.charset.StandardCharsets.UTF_8));return java.util.HexFormat.of().formatHex(hash);}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
